                    streamRequested: activeConfig.llm.stream === true && providerCallOptions.forceNonStreaming !== true,
                    serviceTier: performancePolicy.effectiveTier || flexPolicy.serviceTier || '',
                    flexApplied: flexPolicy.flexApplied === true,
                    systemPrompt: effectiveSystemPrompt,
                    userContent,
                    promptCacheRequested: effectiveOptions?.promptEnvelope?.schema === CANONICAL_PROMPT_ENVELOPE_SCHEMA,
                    stablePrefixDigest: effectiveOptions?.promptEnvelope?.stablePrefixDigest || '',
                    referenceDigest: effectiveOptions?.promptEnvelope?.referenceDigest || '',
