                            requested: activeConfig.llm.stream === true && fallbackCallOptions.forceNonStreaming !== true,
                            used: fallbackResult.streamed === true,
                            provider: providerName,
                            profile: resolved.profile,
                            meta: fallbackResult.streamMeta || {}
