    visible: false,
    activeTab: 'flow',
    sidebarSection: 'home',
    selectedPreset: 'default',
    selectedPrompt: 'ariadne',
    selectedResultStage: 'ariadne',
    dirty: false,
    statusTimer: null,
    refreshTimer: null,
    importText: '',
    debugExportText: '',
    includeSecretsInExport: false,
    exportScope: 'flow',
    providerFilter: '',
    vertexCredentialDrafts: {},
